import random
import math

def task_func(LETTERS=[chr(i) for i in range(97, 123)]):
    result = {}
    for letter in LETTERS:
        list_of_integers = [random.randint(0, 100) for _ in range(random.randint(1, 10))]
        result[letter] = population_stddev(list_of_integers)
    return result

def population_stddev(numbers):
    if len(numbers) == 0:
        return 0
    mean = sum(numbers) / len(numbers)
    variance = sum((x - mean) ** 2 for x in numbers) / len(numbers)
    return math.sqrt(variance)

