import types
import json

def task_func(f):
    if isinstance(f, types.LambdaType):
        is_lambda = True
        signature = inspect.signature(f)
        argspec = list(signature.parameters.keys())
        defaults = signature.defaults
    else:
        is_lambda = False
        signature = inspect.signature(f)
        argspec = list(signature.parameters.keys())
        defaults = signature.defaults
        if defaults:
            defaults = {k: str(v) for k, v in defaults.items()}
        else:
            defaults = {}

    function_specs = {
        'name': f.__name__,
        'arguments': argspec,
        'default_values': defaults,
        'annotations': {
            k: str(v) for k, v in f.__annotations__.items()
        },
        'is_lambda': is_lambda
    }

    return json.dumps(function_specs, indent=4)

