# Constants
BACKUP_DIR = '/tmp/backup'

def get_unique_backup_dir():
    return "/fake/backup/path"

def task_func(directory):
    backup_dir = get_unique_backup_dir()
    errors = []
    try:
        # Check if the directory exists
        if not os.path.exists(directory):
            errors.append(f"Directory '{directory}' does not exist.")
            return (backup_dir, errors)

        # Create backup directory if it doesn't exist
        if not os.path.exists(backup_dir):
            os.makedirs(backup_dir)

        # Copy contents of the directory to the backup directory
        for item in os.listdir(directory):
            src = os.path.join(directory, item)
            dst = os.path.join(backup_dir, item)
            if os.path.isfile(src):
                shutil.copy2(src, dst)
            elif os.path.isdir(src):
                shutil.copytree(src, dst)

        # Clean the original directory by deleting all contents
        shutil.rmtree(directory)

    except Exception as e:
        errors.append(f"An error occurred: {e}")

    return (backup_dir, errors)

